function out = subst_verified(str, pattern, replacement, description, expected_count)
% SUBST_VERIFIED  regexprep that fails loudly when the match count is unexpected.
%
% The frozen model is generated by rewriting the expanded template. A regexprep that
% matches nothing returns the input unchanged, so a stale pattern silently ships a
% frozen model still carrying calibrated values - or, worse, still carrying
% do_parameter_estimation = true - under a header claiming it is frozen. Counting
% matches first turns that class of failure into an error at generation time.
%
% Usage:
%   text = subst_verified(text, pattern, replacement, 'rho_L block', 1)

    if nargin < 5
        expected_count = 1;
    end

    matches = regexp(str, pattern, 'match');
    n = numel(matches);

    if n ~= expected_count
        error('generate_frozen_model:substitutionFailed', ...
            ['Substitution "%s" matched %d time(s), expected %d.\n' ...
             'Pattern: %s\n' ...
             'The frozen model would silently keep the original text. This usually ' ...
             'means the source .mod was reformatted; update the pattern to match.'], ...
            description, n, expected_count, pattern);
    end

    out = regexprep(str, pattern, replacement);

    if strcmp(out, str)
        error('generate_frozen_model:substitutionNoOp', ...
            'Substitution "%s" matched but produced no change. Pattern: %s', ...
            description, pattern);
    end
end
